mapper.update:
UPDATE menu_router set show = (case show when true then false else true end)


        #{id}


        #{id}

UPDATE menu_router
set "rank" = (select min("rank") from menu_router) - 1
where id = #{menuId}

UPDATE menu_router
set "rank" = (select max("rank") from menu_router) + 1
where id = #{menuId}

foreach.trim:
update menu_router

    rank=${item.rank},

        parent_id=${item.parentId},


        menu_type=${item.menuType}


where id = ${item.id}

mapper.select:
with recursive tmp as ( select mr.id, mr.menu_path as menuPath, mr.parent_id as parentId , mr.level, mr.description, mr.menu_key as menuKey, mr."rank", mr.is_menu as menuFlag, mr.show, mr.menu_url menuUrl, mr.menu_type menuType, mr.open_type openType, mr.type, mr.icon, mr.name_cn, mr.name_en, mr.full_url from menu_router mr , sys_role_menu srm , sys_user_roles sur, sys_role sr where mr.id = srm.menu_id and mr."show" = true and srm.checked = true and sur.role_id = srm.role_id and sr.id = sur.role_id and sr.status = true and sur.user_id = #{userId}
and mr.is_menu = #{isMenu}
union all select mr2.id , mr2.menu_path as menuPath, mr2.parent_id as parentId , mr2.level, mr2.description, mr2.menu_key as menuKey, mr2."rank", mr2.is_menu as menuFlag, mr2.show, mr2.menu_url menuUrl, mr2.menu_type menuType, mr2.open_type openType, mr2.type, mr2.icon, mr2.name_cn, mr2.name_en, mr2.full_url from tmp, menu_router mr2 where mr2.id = tmp.parentId and mr2.show = true ) select distinct tmp.* , coalesce((select srm.read_write from sys_role_menu srm , sys_user_roles sur, sys_role sr where tmp.id = srm.menu_id and srm.checked = true and sur.role_id = srm.role_id and sr.id = sur.role_id and sr.status = true and srm.read_write = true and sur.user_id = #{userId} limit 1),false) as writeable from tmp
